/* ============================================================
   PERCEPTUAL GUIDE ENGINE — recommendations are designed to improve
   the whole visual impression, not just one isolated metric.

   The guide maps measurable signals to human-perception principles:
   hierarchy/scale, balance, figure-ground, proximity/grouping,
   contrast, color coherence and visual simplicity.
   ============================================================ */
function perceptualImpactWeight(id, designType){
  var base={
    focus:1.28,
    hierarchy:1.26,
    composition:1.22,
    figureground:1.16,
    type:1.10,
    grouping:1.07,
    contrast:1.06,
    color:0.98,
    exposure:1.02,
    complexity:0.94
  };
  var w=base[id]||1;
  if(designType==='brand' && (id==='hierarchy'||id==='figureground')) w+=0.05;
  if((designType==='content'||designType==='social'||designType==='promotion') && (id==='focus'||id==='type'||id==='contrast')) w+=0.05;
  if(designType==='photo' && (id==='focus'||id==='composition'||id==='exposure')) w+=0.05;
  return w;
}

function exactPerceptualDelta(current,target,min,max){
  var gap=(typeof current==='number'&&typeof target==='number')?Math.max(0,target-current):0.10;
  var pct=Math.round(8+gap*58);
  if(typeof min==='number') pct=Math.max(min,pct);
  if(typeof max==='number') pct=Math.min(max,pct);
  return pct;
}

function nearestAnchorTarget(a,designType){
  var x=a&&a.focus&&typeof a.focus.x==='number'?a.focus.x:.5;
  var y=a&&a.focus&&typeof a.focus.y==='number'?a.focus.y:.5;
  if(designType==='brand'||designType==='project') return {x:50,y:50};
  var pts=[[33,33],[67,33],[33,67],[67,67]], best=pts[0], bd=Infinity;
  for(var i=0;i<pts.length;i++){
    var px=pts[i][0]/100,py=pts[i][1]/100,d=(x-px)*(x-px)+(y-py)*(y-py);
    if(d<bd){bd=d;best=pts[i];}
  }
  return {x:best[0],y:best[1]};
}

function exactSpacingTarget(a){
  var score=a&&a.scores&&typeof a.scores.spacingScore==='number'?a.scores.spacingScore:.62;
  return Math.max(4,Math.min(8,Math.round(4+(0.76-score)*12)));
}

function exactContrastDelta(a){
  var score=a&&a.scores&&typeof a.scores.contrastScore==='number'?a.scores.contrastScore:.62;
  return exactPerceptualDelta(score,.80,8,18);
}

function exactHierarchyDelta(a){
  var score=a&&a.scores&&typeof a.scores.visualHierarchyScore==='number'?a.scores.visualHierarchyScore:.62;
  return exactPerceptualDelta(score,.82,9,20);
}

function exactGroupingDelta(a){
  var score=a&&a.scores&&typeof a.scores.consistencyScore==='number'?a.scores.consistencyScore:.64;
  return exactPerceptualDelta(score,.78,6,14);
}

function exactColorCount(a,designType){
  if(designType==='photo') return null;
  return 3;
}

function psychologyInstruction(id,designType,a){
  var region=regionFrom(a);
  var anchor=nearestAnchorTarget(a,designType);

  if(id==='focus'){
    return 'Keep '+region+' as the first-look area. Strengthen the main subject’s visual weight or separation, but leave supporting details quieter.';
  }
  if(id==='hierarchy'){
    return 'Make the main message or subject clearly dominant. Increase its size, weight, contrast, or isolation rather than enlarging every element.';
  }
  if(id==='composition'){
    return 'Move the main visual toward the nearest useful anchor point (about '+anchor.x+'% from the left and '+anchor.y+'% from the top). Then rebalance the supporting elements around it.';
  }
  if(id==='figureground'){
    return 'Increase separation only around the important visual area: use stronger local contrast, a calmer background, or a cleaner edge. Keep the rest of the image unchanged.';
  }
  if(id==='contrast'){
    return 'Increase contrast where the viewer needs to read or notice something first. Prefer a local change instead of increasing contrast across the whole image.';
  }
  if(id==='grouping'){
    return 'Bring related elements closer together, create a clearly larger gap before the next section, and repeat that spacing rhythm consistently.';
  }
  if(id==='type'){
    return 'Create a clear text hierarchy: one dominant headline, quieter supporting text, and smaller minor details. Do not make every text element equally strong.';
  }
  if(id==='color'){
    if(designType==='photo') return 'Keep one clear color mood. Reduce distracting color casts or competing saturated areas while preserving useful subject color.';
    return 'Use a small, intentional palette: one dominant color, a supporting color, and an accent only where it helps attention. Remove colors that do not have a clear job.';
  }
  if(id==='complexity'){
    return 'Quiet or remove secondary detail near the focal area. Keep useful information and brand character; reduce competition around the main idea.';
  }
  if(id==='exposure'){
    var mean=a&&a.rawScores&&typeof a.rawScores.meanL==='number'?a.rawScores.meanL:128;
    if(mean<105) return 'Lift the darker parts enough for the subject and important details to remain visible, while protecting highlights from clipping.';
    return 'Reduce harsh brightness where needed and protect highlights, while keeping the main subject comfortably visible.';
  }
  return 'Make one focused visual change that strengthens the most important area, then keep the rest stable so Fiko can measure the effect.';
}

function buildAIEditGuide(fd, analysis, designType){
  var findings=(session&&Array.isArray(session.findings)&&session.findings.length)
    ? session.findings.filter(function(x){return x && !x.completed;})
    : (fd?[fd]:[]);
  if(!findings.length && fd) findings=[fd];

  var typeLabel=(DESIGN_TYPES && DESIGN_TYPES[designType] && DESIGN_TYPES[designType].label)
    ? DESIGN_TYPES[designType].label : (designType||'Design');

  var sections=[];
  findings.forEach(function(item,index){
    var problem=item.problem||'This area needs stronger visual treatment.';
    var change=normalizeGuideInstruction(item.instruction||'Improve this area using clear visual hierarchy, spacing, alignment, contrast, and balance.');
    sections.push(
      'PROBLEM '+(index+1)+'\n'+problem+'\n\n'+
      'REQUIRED ACTION\n'+
      '1. Locate the exact visual area described by the problem.\n'+
      '2. Apply the following change exactly as written; treat it as a required instruction, not a suggestion.\n'+
      '3. Make the change strongly enough to be clearly visible while preserving the core subject/message.\n'+
      '4. Rebalance any nearby elements disturbed by the change.\n\n'+
      'EXACT CHANGE\n'+change
    );
  });

  return [
    'EDIT THE PROVIDED IMAGE DIRECTLY. DO NOT RETURN AN EXPLANATION.',
    '',
    'MISSION',
    'Produce the strongest finished version of the provided source image that can be created from the source material.',
    'Treat this as one complete image-editing job. Execute every instruction below in the same edit. Do not work on one problem and stop.',
    'Follow the instructions literally. Do not replace them with your own alternative plan, interpretation, or partial solution.',
    'Do not merely suggest changes, describe changes, or make a partial patch. Perform every requested change directly in the image.',
    '',
    'DESIGN TYPE',
    typeLabel,
    '',
    'REQUIRED PROBLEMS AND EXACT ACTIONS',
    sections.join('\n\n'),
    '',
    'EXECUTION ORDER',
    '1. Start from the provided source image. Do not create an unrelated design from scratch.',
    '2. Complete EVERY numbered problem above during this single editing pass. All problems are mandatory.',
    '3. When an instruction gives a position, percentage, hierarchy, spacing amount, or other target, use that target rather than inventing a different one.',
    '4. When an instruction tells you to move, resize, remove, add, recolor, reframe, or rebalance something, actually perform that operation in the image.',
    '5. After every major change, rebalance connected elements so alignment, spacing, hierarchy, and visual weight remain coherent.',
    '',
    'WHOLE-IMAGE QUALITY PASS',
    'After completing the listed problems, inspect the entire image again from top to bottom and left to right.',
    'Fix any remaining meaningful weakness in composition, focal point, hierarchy, typography, readability, spacing, alignment, color harmony, contrast, negative space, clutter, consistency, or finish.',
    'Do not invent decorative changes just to make the image different. Every extra change must make the design clearer, stronger, more readable, more balanced, or more professional.',
    'Do not stop after fixing the listed items. Continue the whole-image pass until there is no obvious high-impact visual improvement left that can be made safely.',
    '',
    'FINAL CRITICAL CHECK',
    'View the completed image as a finished design, not as an editing task.',
    'Confirm that the main idea is immediately understandable, the primary visual has clear priority, important text is easy to read, spacing and alignment are intentional, colors work together, distractions are controlled, and the composition feels complete.',
    'If any of those checks still fail, correct the image before returning it, then review the whole image again.',
    '',
    'RETURN',
    'Return ONLY the final edited image.'
  ].join('\n');
}
function findingsFor(designType, analysis){
  var displayedPoints = analysis && typeof analysis.overall==='number'
    ? Math.round(Math.max(0,Math.min(100,analysis.overall*100))*10)/10
    : 0;
  if(!analysis || displayedPoints>=75) return [];
  var reliability=analysis.reliability||{};
  var confidence=typeof reliability.confidence==='number'?reliability.confidence:0.70;
  var conservativeScan=confidence<0.80 || (typeof reliability.consistency==='number' && reliability.consistency<0.68);
  var s=analysis.scores;
  var subtype=(session&&session.subType)||'';
  var out=[];
  function add(id,metric,title,problem,instruction,ideal){
    var value=s[metric];
    if(typeof value!=='number') return;
    var target=ideal==null?0.74:ideal;
    var deficit=target-value;
    /* Never create a task for a signal that is already comfortably healthy. */
    if(value>=target || deficit<0.045) return;
    var impact = deficit * perceptualImpactWeight(id, designType);
    var psychologyCopy = psychologyInstruction(id, designType, analysis);
    out.push({
      id:id,metric:metric,verify:metric,targetValue:target,
      title:title,problem:problem,instruction:psychologyCopy,
      aiInstruction:'',
      category:'Perceptual quality',priority:impact>=0.15?'high':impact>=0.09?'medium':'low',
      completed:false,healthAtStart:value,deficit:deficit,impact:impact,subType:subtype,
      originalAnalysis:null,originalMetricBundle:null,baselineAnalysis:null,
      currentAnalysis:null,verificationHistory:[],attempts:0
    });
  }

  if(designType==='photo'){
    add('focus','visualHierarchyScore','Make the subject easier to notice first',
      'The strongest visual area is not separating clearly enough from the rest of the photo.',
      focusInstruction(analysis,'photo'),'0.82');
    add('composition','compositionScore','Give the frame a stronger composition',
      'The visual weight is sitting in a way that makes the frame feel less intentional.',
      compositionInstruction(analysis,'photo'),'0.76');
    add('exposure','exposureScore','Bring the light into a comfortable range',
      'Important light and dark areas are a little too flat or too extreme.',
      'Recover very bright or very dark areas first. Keep the main subject comfortably visible without washing out highlights or crushing shadows.','0.76');
    add('color','harmonyScore','Make the colors work together',
      'The main colors are pulling in different directions instead of supporting the subject.',
      'Keep one clear color mood. Reduce distracting color casts and let the subject keep the strongest useful color contrast.','0.76');
    add('complexity','complexityFitScore','Reduce distraction around the subject',
      'There is more visual detail around the important area than the eye needs.',
      'Simplify or darken only the distracting areas around the subject. Keep useful detail; remove competition, not character.','0.74');
  } else if(designType==='brand'){
    add('hierarchy','visualHierarchyScore','Make the brand mark read first',
      'The main mark does not clearly dominate the visual field.',
      'Give the primary mark the strongest visual weight. Keep supporting details quieter and leave a clean buffer around the mark.','0.80');
    add('figureground','figureGroundScore','Separate the mark from its background',
      'The main shape is blending into the background in places.',
      'Increase the visual separation between the mark and its background so the shape is clear at a glance.','0.80');
    add('composition','compositionScore','Center the visual weight',
      'The main visual mass feels slightly off-balance inside the frame.',
      compositionInstruction(analysis,'brand'),'0.76');
    add('color','harmonyScore','Make the brand colors feel intentional',
      'The color relationship is less cohesive than it could be.',
      'Keep a small, repeatable color system: one main color, a supporting tone, and an accent only when it has a job.','0.76');
    add('grouping','consistencyScore','Clean up alignment and spacing',
      'Related elements do not feel like they belong to the same system.',
      'Use shared edges and repeatable gaps. Keep related pieces close and unrelated pieces clearly separated.','0.75');
  } else if(designType==='content'){
    add('focus','visualHierarchyScore','Make the main idea hit faster',
      'The eye does not get a clear first target quickly enough.',
      hierarchyInstruction(analysis,'content'),'0.80');
    add('type','typographyHierarchyScore','Make the headline clearly dominant',
      'Primary and supporting text are too close in visual weight.',
      'Make the main headline exactly '+exactAdjustmentPct(analysis&&analysis.scores?analysis.scores.typographyHierarchyScore:null,.80,7,22)+'% larger or bolder than supporting text. Keep the supporting copy quieter.','0.80');
    add('figureground','figureGroundScore','Separate the important element from the background',
      'The main subject or message is blending into nearby detail.',
      'Increase separation only where the eye needs it: stronger contrast, calmer background, or a cleaner local area behind the main element.','0.80');
    add('composition','compositionScore','Reframe the main content',
      'The key subject and supporting elements are not using the frame efficiently.',
      compositionInstruction(analysis,'content'),'0.76');
    add('complexity','complexityFitScore','Remove competing detail',
      'The thumbnail/cover has more visual competition than the main message needs.',
      'Remove or quiet secondary elements. Keep one main idea, one strong supporting visual, and enough empty space to separate them.','0.74');
  } else if(designType==='promotion'){
    add('hierarchy','visualHierarchyScore','Make the offer impossible to miss',
      'The main message does not clearly lead the visual hierarchy.',
      hierarchyInstruction(analysis,'promotion'),'0.81');
    add('contrast','contrastScore','Increase the main message contrast',
      'The important message is blending into its background.',
      'Increase contrast only for the main headline or offer. Keep secondary text quieter so the eye has one clear entry point.','0.78');
    add('composition','compositionScore','Give the layout a stronger structure',
      'The main image, message and action do not feel intentionally arranged.',
      compositionInstruction(analysis,'promotion'),'0.77');
    add('grouping','consistencyScore','Group related information',
      'Related details are visually separated while some unrelated items sit too close.',
      'Keep headline + key detail together. Separate that group from secondary information with one larger, consistent gap.','0.76');
    add('color','harmonyScore','Control the accent colors',
      'Too many color relationships are competing for attention.',
      'Use one dominant color and one accent for attention. Keep secondary information neutral or quieter.','0.76');
  } else if(designType==='project'){
    add('hierarchy','visualHierarchyScore','Make the key point obvious',
      'Everything is asking for attention at nearly the same level.',
      hierarchyInstruction(analysis,'project'),'0.80');
    add('type','typographyHierarchyScore','Create a clear text size ladder',
      'Headings and supporting text are not separated enough.',
      'Make each heading level clearly different. The main title should be the strongest, section heads next, body copy last.','0.79');
    add('grouping','consistencyScore','Group related information',
      'The layout does not show clear relationships between nearby content blocks.',
      'Move related items closer together and use a larger gap between separate sections. Repeat the same spacing pattern.','0.76');
    add('composition','compositionScore','Use the frame more intentionally',
      'The page has uneven visual weight or empty areas that do not feel deliberate.',
      compositionInstruction(analysis,'project'),'0.76');
    add('contrast','contrastScore','Improve readability contrast',
      'Some important content is too close in tone to its background.',
      'Increase contrast for headings and key values first. Body text can stay quieter, but it should still be easy to read.','0.78');
  } else if(designType==='social'){
    add('focus','visualHierarchyScore','Give the post one clear first look',
      'The eye is not being pulled to one obvious starting point.',
      hierarchyInstruction(analysis,'social'),'0.80');
    add('type','typographyHierarchyScore','Make the main message dominant',
      'The main message and supporting text are competing too closely.',
      'Make the main message exactly '+exactAdjustmentPct(analysis&&analysis.scores?analysis.scores.typographyHierarchyScore:null,.79,7,22)+'% larger or bolder than supporting text and keep the supporting copy visually quieter.','0.79');
    add('contrast','contrastScore','Make the key text easier to read',
      'Important text is blending into the image behind it.',
      'Increase contrast behind the key message, preferably only where the text sits. Avoid making the whole image heavy.','0.78');
    add('composition','compositionScore','Balance the frame',
      'The main visual weight is not placed as intentionally as it could be.',
      compositionInstruction(analysis,'social'),'0.76');
    add('complexity','complexityFitScore','Quiet the visual noise',
      'Too many details are competing with the message.',
      'Reduce only secondary detail around the focal area. Keep the parts that add meaning or brand character.','0.74');
  } else {
    add('focus','visualHierarchyScore','Create a clear focal point',
      'The eye does not get a clear first target quickly enough.',
      hierarchyInstruction(analysis,'general'),'0.79');
    add('composition','compositionScore','Improve the composition',
      'The visual weight can be arranged more intentionally.',
      compositionInstruction(analysis,'general'),'0.76');
    add('contrast','contrastScore','Improve important contrast',
      'Some important visual information is not separating enough from its background.',
      'Increase contrast where the eye needs information most. Avoid increasing contrast everywhere at once.','0.77');
    add('color','harmonyScore','Make the color relationships more coherent',
      'The colors are competing more than they are working together.',
      'Keep one dominant color relationship and one accent. Reduce colors that do not help the main message.','0.76');
    add('complexity','complexityFitScore','Reduce unnecessary visual noise',
      'The image has competing detail that slows down the first read.',
      'Quiet or remove secondary detail near the focal area, while keeping the useful information.','0.74');
  }

  /*
    Always give the user a useful next step while the image is below 75.
    Sometimes the overall score can remain below the ready threshold even when
    no single tracked signal is far enough below its task threshold.
  */
  if(out.length===0 && displayedPoints<75){
    out.push({
      id:'polish',
      metric:null,
      verify:'overall',
      targetValue:null,
      title:'Finish the overall visual polish',
      problem:'The image is not fully ready to use yet. The design needs a stronger overall balance between its main idea, hierarchy, spacing, clarity, and visual polish.',
      instruction:'Make a full visual pass. Strengthen the main focal point, clean up spacing and alignment, improve readability and color relationships, and remove anything that competes with the main idea.',
      aiInstruction:'',
      category:'Perceptual quality',
      priority:'high',
      completed:false,
      healthAtStart:analysis.overall,
      deficit:0.75-analysis.overall,
      impact:0.50,
      subType:subtype,
      originalAnalysis:null,originalMetricBundle:{},baselineAnalysis:null,
      currentAnalysis:null,verificationHistory:[],attempts:0
    });
  }

  /* Rank by estimated whole-design perceptual impact, not by the size of one isolated metric gap. */
  out.sort(function(a,b){ return (b.impact-a.impact) || (b.deficit-a.deficit); });
  out.forEach(function(fd){ fd.aiInstruction=buildAIEditGuide(fd,analysis,designType); });
  var limit=conservativeScan?2:4;
  out=out.slice(0,limit);
  if(conservativeScan){
    out.forEach(function(fd){
      fd.priority=fd.priority==='high'?'high':'medium';
      fd.problem='Fiko found a possible improvement, but the image signals were not highly consistent. '+fd.problem;
    });
  }
  return out;
}

function regionFrom(a){
  if(!a || !a.focus) return 'near the strongest visual area';
  var x=a.focus.x, y=a.focus.y;
  var h=y<.34?'top':y>.66?'bottom':'middle';
  var v=x<.34?'left':x>.66?'right':'center';
  if(v==='center' && h==='middle') return 'near the center';
  return h+'-'+v;
}
function exactAdjustmentPct(current,target,min,max){
  var gap=(typeof current==='number'&&typeof target==='number') ? Math.max(0,target-current) : 0.08;
  var pct=Math.round((6 + gap*70));
  if(typeof min==='number') pct=Math.max(min,pct);
  if(typeof max==='number') pct=Math.min(max,pct);
  return pct;
}
function exactBreathingPct(a){
  var x=a&&a.focus&&typeof a.focus.x==='number'?a.focus.x:.5;
  var y=a&&a.focus&&typeof a.focus.y==='number'?a.focus.y:.5;
  var edge=Math.min(x,1-x,y,1-y);
  return Math.max(6,Math.min(12,Math.round(6 + (0.25-Math.max(0,edge-.08))*18)));
}
function compositionInstruction(a,purpose){
  var x=a&&a.focus&&typeof a.focus.x==='number'?a.focus.x:.5;
  var y=a&&a.focus&&typeof a.focus.y==='number'?a.focus.y:.5;
  var moves=[];
  var horizontal='',vertical='';
  if(x>.62){ horizontal='Move the main visual '+Math.round(8+(x-.62)*24)+'% to the left'; }
  else if(x<.38){ horizontal='Move the main visual '+Math.round(8+(.38-x)*24)+'% to the right'; }
  if(y>.62){ vertical='move the main visual '+Math.round(10+(y-.62)*26)+'% upward'; }
  else if(y<.38){ vertical='move the main visual '+Math.round(10+(.38-y)*26)+'% downward'; }
  if(horizontal) moves.push(horizontal);
  if(vertical){
    if(moves.length) moves[moves.length-1]+=' and '+vertical.replace(/^move /,'');
    else moves.push(vertical.charAt(0).toUpperCase()+vertical.slice(1));
  }
  var breathing=exactBreathingPct(a);
  if(!moves.length){
    return 'Keep the main visual close to the current center/anchor. Leave exactly '+breathing+'% breathing room around the important content and keep secondary elements balanced around it.';
  }
  return moves.join('. ')+'. Keep exactly '+breathing+'% breathing room from the nearest edge around the important content, and keep supporting elements balanced around it.';
}
function hierarchyInstruction(a,purpose){
  var r=regionFrom(a);
  var current=a&&a.scores&&typeof a.scores.visualHierarchyScore==='number'?a.scores.visualHierarchyScore:.65;
  var target=.80;
  var pct=exactAdjustmentPct(current,target,7,24);
  return 'Use '+r+' as the visual anchor. Give the most important element exactly '+pct+'% more visual weight than it has now, then quiet the secondary details around it.';
}
function focusInstruction(a,purpose){
  var r=regionFrom(a);
  var current=a&&a.scores&&typeof a.scores.visualHierarchyScore==='number'?a.scores.visualHierarchyScore:.65;
  var pct=exactAdjustmentPct(current,.82,7,22);
  return 'Keep the main subject in or near '+r+'. Increase its separation from nearby detail by exactly '+pct+'%, so one area becomes the obvious first look.';
}

var PRI_COLOR = { high:'var(--bad)', medium:'var(--warn)', low:'var(--good)' };
var PRI_LABEL = { high:'High priority', medium:'Medium priority', low:'Low priority' };

/* quality range + level */
function qualityFromScore(score0to1){
  var pts=Math.round(Math.max(0,Math.min(100,score0to1*100))*10)/10;
  var excellent=pts>=75;
  var good=pts>60 && pts<75;
  return {
    points:pts,
    lo:Math.floor(pts),
    hi:Math.ceil(pts),
    level:excellent?3:(good?2:1),
    name:excellent?'Excellent':(good?'Good':'Needs improvement'),
    sub:excellent
      ? 'Your design already has a strong overall look. No important improvements are required.'
      : good
        ? 'Your design is good. A few focused changes could make it feel even stronger.'
        : 'Fiko found a few important visual improvements that could make the design clearer and stronger.',
    color:excellent?'var(--fiko-mint)':good?'var(--fiko-coral)':'var(--fiko-rose)',
    excellent:excellent,
    good:good
  };
}

/* ============================================================
   6. VERIFICATION — compares a reuploaded image to the previous
   snapshot using the same real pixel engine. Directional checks
   per finding type; falls back to a generic "did it change
   enough" check for non-measurable categories.
============================================================ */
/*
  Perceptual verification layer.
  A task is not verified from one metric or one upload-to-upload delta.
  It keeps its original baseline, also looks at the latest edit direction,
  and asks whether several related visual signals agree.
*/
/* Global task-signal helpers used by the analysis/verification service layer.
   These must live outside the SIMPLE CHECKLIST IIFE so the initial scan runner
   and the verification engine can both access them. */
function taskSignalProfile(task){
  var profiles={
    focus:{visualHierarchyScore:.34,figureGroundScore:.28,saliencyScore:.20,placementScore:.18},
    composition:{compositionScore:.34,balanceScore:.20,placementScore:.20,negativeSpaceScore:.14,spacingScore:.12},
    exposure:{exposureScore:.42,clarityScore:.32,contrastScore:.26},
    color:{harmonyScore:1},
    complexity:{complexityFitScore:.44,clarityScore:.30,figureGroundScore:.26},
    hierarchy:{visualHierarchyScore:.40,saliencyScore:.22,figureGroundScore:.20,contrastScore:.18},
    figureground:{figureGroundScore:.48,clarityScore:.28,contrastScore:.24},
    grouping:{consistencyScore:.34,alignmentScore:.26,spacingScore:.22,negativeSpaceScore:.18},
    type:{typographyHierarchyScore:.46,visualHierarchyScore:.28,contrastScore:.26}
  };
  return profiles[task && task.id] || (task && task.metric ? {[task.metric]:1} : {});
}

function weightedTaskScore(task,a){
  if(!a || !a.scores) return null;
  var s=a.scores, p=taskSignalProfile(task), total=0, weight=0;
  Object.keys(p).forEach(function(k){
    if(typeof s[k]==='number'){ total += s[k]*p[k]; weight += p[k]; }
  });
  return weight ? total/weight : null;
}

function taskMetricBundle(task, analysis){
  if(!analysis || !analysis.scores) return {};
  var p=taskSignalProfile(task), out={};
  Object.keys(p).forEach(function(k){
    if(typeof analysis.scores[k]==='number') out[k]=analysis.scores[k];
  });
  return out;
}

function calculateTaskEvidence(task, baseline, previous, current){
  if(!task || !baseline || !previous || !current) return {
    pass:false, evidence:0, baselineProgress:0, latestDirection:0,
    relatedSignalAgreement:0, regressionPenalty:0, reason:'Not enough scan history.'
  };

  var b=baseline.scores||{}, p=previous.scores||{}, c=current.scores||{};
  var profile=taskSignalProfile(task);
  var keys=Object.keys(profile);
  if(!keys.length) return {pass:false,evidence:0,reason:'No perceptual bundle is available for this task.'};

  var bTask=weightedTaskScore(task,baseline);
  var pTask=weightedTaskScore(task,previous);
  var cTask=weightedTaskScore(task,current);
  if(bTask===null || pTask===null || cTask===null) return {pass:false,evidence:0,reason:'The task could not be measured from this image.'};

  /*
    Verification is task-first, not global-score-first.

    An AI edit can improve the intended perceptual property while leaving the
    whole-design score almost flat because the image-analysis heuristics are
    not a perfect substitute for human judgement. We therefore require the
    requested signal bundle to improve, while using the overall score only as
    a regression guard.
  */
  var baselineProgress=cTask-bTask;
  var latestDirection=cTask-pTask;

  var weightedPositive=0, weightedNegative=0;
  var positiveSignals=0, negativeSignals=0;
  var totalWeight=0;

  keys.forEach(function(k){
    var w=profile[k], bv=b[k], pv=p[k], cv=c[k];
    if(typeof bv!=='number'||typeof pv!=='number'||typeof cv!=='number') return;
    totalWeight+=w;

    var bd=cv-bv, ld=cv-pv;

    /* Small movements are treated as measurement noise. */
    var progressScore=clamp01((bd+0.001)/0.012);
    var directionScore=clamp01((ld+0.0005)/0.009);

    weightedPositive += w*(0.66*progressScore + 0.34*directionScore);

    if(bd>0.0015 || ld>0.0010) positiveSignals++;
    if(bd<-0.028 || ld<-0.032) negativeSignals++;

    if(bd<0) weightedNegative += w*Math.min(1,Math.abs(bd)/0.035);
    if(ld<0) weightedNegative += w*0.45*Math.min(1,Math.abs(ld)/0.025);
  });

  var relatedSignalAgreement=totalWeight?weightedPositive/totalWeight:0;
  var regressionPenalty=totalWeight?weightedNegative/totalWeight:0;

  var overallBaseline=typeof b.overall==='number'?b.overall:baseline.overall;
  var overallPrevious=typeof p.overall==='number'?p.overall:previous.overall;
  var overallCurrent=typeof c.overall==='number'?c.overall:current.overall;
  var overallMovement=overallCurrent-overallBaseline;
  var latestOverallDirection=overallCurrent-overallPrevious;

  /* Overall score supports the decision but does not decide it. */
  if(latestOverallDirection < -0.035) regressionPenalty=Math.min(1,regressionPenalty+0.20);

  var baselineEvidence=clamp01((baselineProgress+0.001)/0.012);
  var directionEvidence=clamp01((latestDirection+0.0005)/0.009);
  var overallSupport=clamp01((overallMovement+0.001)/0.020);

  var evidence =
    0.44*baselineEvidence +
    0.30*directionEvidence +
    0.22*relatedSignalAgreement +
    0.04*overallSupport -
    0.24*regressionPenalty;

  /*
    Pass when the requested perceptual bundle shows a real improvement,
    the newest upload did not strongly undo it, and the image has not suffered
    a meaningful whole-design regression.
  */
  var taskImproved =
    baselineProgress >= 0.0010 ||
    latestDirection >= 0.0010 ||
    positiveSignals >= 1;

  var latestStable = latestDirection >= -0.012;
  var noMajorRegression = regressionPenalty < 0.65;

  var pass =
    evidence >= 0.28 &&
    taskImproved &&
    noMajorRegression;

  return {
    pass:pass,
    evidence:clamp01(evidence),
    baselineProgress:baselineProgress,
    latestDirection:latestDirection,
    relatedSignalAgreement:relatedSignalAgreement,
    regressionPenalty:regressionPenalty,
    positiveSignals:positiveSignals,
    negativeSignals:negativeSignals,
    taskScore:{baseline:bTask,previous:pTask,current:cTask},
    overallMovement:overallMovement,
    latestOverallDirection:latestOverallDirection
  };
}

function detectRegression(task, previousState, currentAnalysis){
  if(!task || !previousState || !currentAnalysis) return {regressed:false,penalty:0};
  var prev=previousState.scores||{}, cur=currentAnalysis.scores||{};
  var profile=taskSignalProfile(task), total=0, drop=0, severe=0;
  Object.keys(profile).forEach(function(k){
    var w=profile[k], a=prev[k], b=cur[k];
    if(typeof a!=='number'||typeof b!=='number') return;
    total+=w;
    var d=b-a;
    if(d<0) drop+=w*Math.min(1,Math.abs(d)/0.025);
    if(d<-0.035) severe+=w;
  });
  var penalty=total?drop/total:0;
  var overallDrop=(typeof prev.overall==='number'&&typeof cur.overall==='number')?prev.overall-cur.overall:0;
  if(overallDrop>0.035) penalty=Math.min(1,penalty+0.20);
  return {
    regressed:penalty>=0.55 || severe>=0.45,
    penalty:penalty,
    overallDrop:overallDrop
  };
}

/* Compatibility wrapper for the older guide renderer. The simple checklist
   uses calculateTaskEvidence directly; this wrapper keeps old dead-path code
   from reintroducing the former one-metric verification rule. */
function verifyFix(finding, beforeAnalysis, afterAnalysis, beforeImgData, afterImgData){
  var similarity=beforeImgData&&afterImgData ? perceptualSimilarityData(beforeImgData,afterImgData) : 0;
  if(similarity>=0.99998){
    return {
      pass:false,
      unchanged:true,
      message:'Fiko could not detect a meaningful visual change in the new image yet.'
    };
  }

  var result=calculateTaskEvidence(
    finding,
    finding.baselineAnalysis||beforeAnalysis,
    beforeAnalysis,
    afterAnalysis
  );

  var previousOverall=beforeAnalysis&&typeof beforeAnalysis.overall==='number' ? beforeAnalysis.overall : 0;
  var currentOverall=afterAnalysis&&typeof afterAnalysis.overall==='number' ? afterAnalysis.overall : 0;
  var overallDrop=previousOverall-currentOverall;

  /*
    A targeted edit is allowed to keep the global score flat or move it a
    little because perceptual improvements are not always captured equally
    by every image heuristic. Only a meaningful whole-image regression blocks
    verification.
  */
  if(result.pass && overallDrop>0.025){
    result.pass=false;
    result.scoreRegression=true;
    result.message='The requested area improved, but the new version caused a noticeable whole-design drop. Keep the useful change and rebalance the rest before verifying it.';
    return result;
  }

  if(result.pass){
    result.message =
      currentOverall>=previousOverall
        ? 'Verified improvement — the requested visual change improved the design without a meaningful regression.'
        : 'Verified improvement — the requested visual change improved while the small overall score movement stayed within tolerance.';
  } else if(!result.message){
    result.message='Fiko could see the update, but the requested visual improvement was not supported by enough evidence yet.';
  }

  return result;
}

function perceptualSimilarityData(a,b){
  var n=Math.min(a.length,b.length), rgb=0,gray=0,c=0;
  for(var i=0;i<n;i+=4){
    var ar=a[i],ag=a[i+1],ab=a[i+2],br=b[i],bg=b[i+1],bb=b[i+2];
    rgb+=(Math.abs(ar-br)+Math.abs(ag-bg)+Math.abs(ab-bb))/3;
    var al=.299*ar+.587*ag+.114*ab, bl=.299*br+.587*bg+.114*bb;
    gray+=Math.abs(al-bl); c++;
  }
  if(!c) return 0;
  return clamp01(1-((rgb/c)/255*.45+(gray/c)/255*.55));
}

