/* ---------- Navigation ---------- */

var app=document.getElementById('app');
var appNav=document.getElementById('appNav');

function setActiveNav(name){
  document.querySelectorAll('.navlink').forEach(function(b){
    b.classList.toggle('active',b.dataset.nav===name);
  });
}
function showAppNav(show){appNav.classList.toggle('hidden',!show);}

function go(view,opts){
  opts=opts||{};
  var fallback=document.getElementById('bootFallback');
  try{
    window.scrollTo(0,0);
    showAppNav(view!=='landing');
    setActiveNav(view);
    if(!RENDERERS[view]) throw new Error('Unknown Fiko view: '+view);
    RENDERERS[view](opts);
    requestAnimationFrame(function(){
      document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('in');});
    });
    mountFikoSlots();
    if(fallback) fallback.hidden=true;
  }catch(err){
    console.error('Fiko runtime error',err);
    if(fallback){ fallback.hidden=false; var fp=fallback.querySelector('p'); if(fp) fp.textContent='Something went wrong. Please refresh the page.'; }
    if(app){ app.innerHTML=''; }
  }
}

var landingMascotTimer=null;
function startLandingMascot(){ if(landingMascotTimer){clearTimeout(landingMascotTimer);landingMascotTimer=null;} return;
  if(landingMascotTimer) clearTimeout(landingMascotTimer);
  var stage=document.getElementById('landingMascot');
  if(!stage) return;
  stage.classList.remove('show-thumbs');
  landingMascotTimer=setTimeout(function(){
    var live=document.getElementById('landingMascot');
    if(!live) return;
    live.classList.add('show-thumbs');
    landingMascotTimer=setTimeout(function(){
      var again=document.getElementById('landingMascot');
      if(!again) return;
      again.classList.remove('show-thumbs');
      startLandingMascot();
    },3600);
  },10000);
}
function mountFikoSlots(){
  if(landingMascotTimer && !document.getElementById('landingMascot')){ clearTimeout(landingMascotTimer); landingMascotTimer=null; }
  document.querySelectorAll('[data-fiko]').forEach(function(el){
    var state=el.getAttribute('data-fiko')||'normal';
    var size=parseInt(el.getAttribute('data-fiko-size')||'56',10);
    var body=el.getAttribute('data-fiko-body')==='1';
    var cls=el.getAttribute('data-fiko-class')||'';
    el.innerHTML=body?fikoBody(state,size,{className:cls}):fikoSVG(state,size,{className:cls});
  });
  var navSlot=document.getElementById('navFikoSlot');
  if(navSlot) navSlot.innerHTML=fikoSVG('normal',30);
  if(document.getElementById('landingMascot')) startLandingMascot();
}

/* ---------- Render helpers ---------- */

function trackerHTML(findings,currentIndex,mode){
  var total=findings.length;
  if(!total) return '';
  var done=findings.filter(function(f){return !!f.completed;}).length;
  if(mode==='final') done=total;
  var pct=Math.round(done/total*100);
  var active=currentIndex>=0?currentIndex:findings.findIndex(function(f){return !f.completed;});
  if(active<0) active=total-1;
  if(active>=total) active=total-1;
  var taskWord=total===1?'task':'tasks';
  var html='<div class="task-progress" aria-label="Task progress">'+
    '<div class="task-progress-head"><span>Progress</span><b>'+done+'/'+total+'</b></div>'+
    '<div class="task-progress-rail">'+
      '<div class="task-progress-fill" style="width:'+pct+'%"></div>'+
      '<span class="task-progress-start" aria-hidden="true"></span>'+ 
      '<div class="task-progress-stops">';
  findings.forEach(function(f,i){
    var completed=!!f.completed;
    var current=(i===active && !completed);
    html+='<div class="task-progress-stop '+(completed?'done ':'')+(current?'current':'')+'" style="left:'+(((i+1)/total)*100)+'%">'+
      '<span class="task-progress-tick">'+(completed?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round"><path d="M5 12l4 4 10-10"/></svg>':'')+'</span><span class="task-progress-label">'+(i+1)+'</span></div>';
  });
  html+='</div></div>'+
    '<div class="task-progress-caption"><b>'+done+' of '+total+'</b> '+taskWord+' completed</div>'+ 
    '</div>';
  return html;
}

function qualityCardHTML(q){
  return '<div class="card quality-card stage-in">'+
    '<div class="quality-level-tag" style="background:color-mix(in srgb, '+q.color+' 16%, transparent);color:'+q.color+';">Level '+q.level+' — '+q.name+'</div>'+
    '<div class="quality-range">'+q.lo+'–'+q.hi+'</div>'+
    '<div class="quality-label">'+q.sub+'</div>'+
    '<div class="quality-bar-track"><div class="quality-bar-fill" style="background:'+q.color+';" data-w="'+q.points+'"></div></div>'+
  '</div>';
}
function animateBars(root){
  requestAnimationFrame(function(){
    root.querySelectorAll('[data-w]').forEach(function(b){
      setTimeout(function(){b.style.width=b.getAttribute('data-w')+'%';},50);
    });
  });
}

function scanEvidenceHTML(a){
  var s=a.scores||{}, r=a.reliability||{};
  function pct(v){return typeof v==='number'?Math.round(v*100)+'%':'—';}
  var conf=typeof r.confidence==='number'?Math.round(r.confidence*100):null;
  var consistency=typeof r.consistency==='number'?Math.round(r.consistency*100):null;
  return '<div class="scan-evidence card">'+
    '<div class="scan-evidence-head"><b>What Fiko measured</b><span>Multi-signal image analysis</span></div>'+
    '<div class="scan-metrics">'+
      '<div><b>'+a.W+' × '+a.H+'</b><span>Analysis size</span></div>'+
      '<div><b>'+pct(s.contrastScore)+'</b><span>Contrast</span></div>'+
      '<div><b>'+pct(s.harmonyScore)+'</b><span>Color harmony</span></div>'+
      '<div><b>'+pct(s.compositionScore)+'</b><span>Composition</span></div>'+
      '<div><b>'+pct(s.alignmentScore)+'</b><span>Alignment</span></div>'+
      '<div><b>'+pct(s.spacingScore)+'</b><span>Spacing</span></div>'+
    '</div>'+
    '<div class="scan-reliability" style="margin-top:12px;padding:10px 12px;border-radius:12px;background:var(--surface-2);font-size:12px;line-height:1.45;">'+
      '<b>Scan confidence '+(conf===null?'available':conf+'%')+'</b>'+
      (consistency===null?'':' · two-scale consistency '+consistency+'%')+
      '<div style="color:var(--ink-soft);margin-top:3px;">Fiko compares two image resolutions so small resizing, compression, and edge noise are less likely to change the result.</div>'+
    '</div>'+
  '</div>';
}

